export const KEY='top-manta-universitats-v1';
export const STAGES=['Per explorar','Prioritari','Preparant proposta','Contactat','En conversa','Proposta enviada','Confirmat','Tancat'];
export const TOPICS={
 Moda:{title:'Moda amb veu pròpia: identitat, treball i antiracisme',en:'Fashion with a voice: identity, work and anti-racism',format:'Xerrada de 60–90 min + debat',workshop:'Taller de 3 h: llegir una peça i transformar-ne el relat; resultat: un concepte de col·lecció amb criteris socials.'},
 Disseny:{title:'Dissenyar des de la comunitat: el cas Top Manta',en:'Community-led design: the Top Manta experience',format:'Classe convidada de 90 min',workshop:'Taller de 3 h: codissenyar un cartell o una proposta visual; resultat: prototip i criteris de representació.'},
 Cooperativisme:{title:'De l’autoorganització al projecte cooperatiu',en:'From self-organisation to a cooperative project',format:'Seminari de 90 min amb estudi de cas',workshop:'Taller de 3 h: simular decisions col·lectives, ingressos i repartiment de responsabilitats; resultat: mapa de governança.'},
 'Economia social':{title:'Treball digne i economies de suport mutu',en:'Dignified work and economies of mutual support',format:'Seminari de 90 min',workshop:'Taller de 3 h: cartografiar recursos, aliances i tensions d’una iniciativa col·lectiva; resultat: model econòmic inicial.'},
 'Polítiques públiques':{title:'Dret a la ciutat, treball i organització mantera',en:'The right to the city, work and migrant-led organising',format:'Ponència de 45 min + conversa de 45 min',workshop:'Taller de 2 h: contrastar una política urbana amb experiències viscudes; resultat: preguntes i propostes de canvi.'},
 Migracions:{title:'Veu pròpia: migracions, drets i autoorganització',en:'Speaking for ourselves: migration, rights and self-organisation',format:'Seminari de 90 min amb debat',workshop:'Taller de 2 h: analitzar discursos sobre migració i construir un contrarelat; resultat: pautes de comunicació sense estereotips.'}
};
export function topic(r){return TOPICS[r.tags.find(t=>TOPICS[t])]||TOPICS.Disseny;}
export function score(r,mode='international'){return mode==='fit'?r.fit*10+r.reach*2:r.fit*6+r.reach*6;}
export function safeURL(s){try{const u=new URL(s);return u.protocol==='https:'?u.href:'';}catch{return '';}}
export function cleanWork(w={}){const o={};for(const k of ['owner','next','notes','contactName','last','date','honorarium','travel'])o[k]=typeof w[k]==='string'?w[k].slice(0,8000):'';o.stage=STAGES.includes(w.stage)?w.stage:STAGES[0];return o;}
export function validateState(v){if(!v||v.version!==1||!v.work||typeof v.work!=='object'||Array.isArray(v.work)||!Array.isArray(v.custom))throw Error('Còpia universitària incompatible.');const work=Object.fromEntries(Object.entries(v.work).slice(0,2000).filter(([k])=>/^[a-zA-Z0-9_-]+$/.test(k)).map(([k,w])=>[k,cleanWork(w)]));const custom=v.custom.slice(0,500).map(r=>{if(!r||typeof r.id!=='string'||!/^custom-[a-zA-Z0-9_-]+$/.test(r.id)||typeof r.name!=='string'||!r.name.trim())throw Error('Fitxa personal incompleta.');const o={};for(const k of ['id','name','country','city','region','kind','unit','source','contactUrl','who','email','contactLevel','angle','route','reviewed'])o[k]=typeof r[k]==='string'?r[k].slice(0,2000):'';o.source=safeURL(o.source);o.contactUrl=safeURL(o.contactUrl);o.tags=Array.isArray(r.tags)?r.tags.filter(t=>typeof t==='string').slice(0,10):['Disseny'];o.fit=Math.min(5,Math.max(1,Number(r.fit)||3));o.reach=Math.min(5,Math.max(1,Number(r.reach)||3));return o;});if(new Set(custom.map(r=>r.id)).size!==custom.length)throw Error('Hi ha identificadors duplicats.');return{version:1,work,custom};}
export function filterRows(rows,f,work){const q=(f.q||'').toLocaleLowerCase();return rows.filter(r=>(!q||[r.name,r.city,r.country,r.unit,r.who,r.angle,...r.tags].join(' ').toLocaleLowerCase().includes(q))&&(!f.region||r.region===f.region)&&(!f.tag||r.tags.includes(f.tag))&&(!f.contact||r.contactLevel===f.contact)&&(!f.stage||(work[r.id]?.stage||STAGES[0])===f.stage)).sort((a,b)=>score(b,f.mode)-score(a,f.mode)||a.name.localeCompare(b.name));}
export function csvCell(v){let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
export function outreach(r,language='en'){const t=topic(r);return language==='ca'?`Assumpte: Proposta de sessió amb Top Manta · ${r.unit}\n\nBon dia,\n\nUs escric com a persona voluntària de comunicació i educació de Top Manta, per explorar una col·laboració amb ${r.name}.\n\nProposem «${t.title}», una sessió que connecti l’experiència de Top Manta amb ${r.unit}. L’angle que proposem és: ${r.angle}\n\nPodem valorar una xerrada amb debat o un taller participatiu, en línia o presencial. Ens podríeu indicar qui coordina aquestes activitats i si disposeu de pressupost per a honoraris i, si cal, desplaçament, allotjament i interpretació?\n\nUs podem fer arribar una fitxa amb objectius, format i necessitats. Dates, llengua i disponibilitat de les persones ponents es concretarien conjuntament.\n\nMoltes gràcies,\n[Nom i contacte]`:`Subject: Guest session with Top Manta · ${r.unit}\n\nDear ${r.name} team,\n\nI am writing as a communications and education volunteer supporting Top Manta in Barcelona, to explore a guest session with your team.\n\nWe would like to propose “${t.en}”, connecting Top Manta’s experience of migrant-led self-organisation, collective production and anti-racism with your teaching or research. We see a possible connection with ${r.unit}.\n\nWe could explore a talk and discussion or a participatory workshop, online or in person. Could you direct us to the person who coordinates guest sessions and let us know whether a budget is available for speaker fees and, if relevant, travel, accommodation and interpretation?\n\nWe can share a one-page proposal. Dates, teaching language, speakers and availability would be agreed together.\n\nThank you,\n[Name and contact details]`;}
